using System;using System.Windows;using System.Windows.Controls;using System.Windows.Markup;using System.Windows.Media;
internal static class SuiteChrome {
 const string Markup="<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Border x:Name='Chrome' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='4'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Chrome' Property='Opacity' Value='0.85'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='Chrome' Property='Opacity' Value='0.65'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Chrome' Property='BorderBrush' Value='{DynamicResource {x:Static SystemColors.HighlightBrushKey}}'/><Setter TargetName='Chrome' Property='BorderThickness' Value='2'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter TargetName='Chrome' Property='Opacity' Value='0.35'/></Trigger></ControlTemplate.Triggers></ControlTemplate>";
 public static void Apply(Button button,string? glyph=null){button.Width=button.Height=button.MinWidth=button.MinHeight=32;button.Padding=new Thickness(0);button.Background=Brushes.Transparent;button.BorderBrush=SystemParameters.HighContrast?SystemColors.WindowTextBrush:new SolidColorBrush(Color.FromArgb(40,128,128,128));button.BorderThickness=new Thickness(1);button.VerticalAlignment=VerticalAlignment.Center;button.Template=(ControlTemplate)XamlReader.Parse(Markup);if(glyph!=null)button.Content=new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=14,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};else if(button.Content is TextBlock text){text.FontFamily=new FontFamily("Segoe Fluent Icons");text.FontSize=14;}}
 public const double HeaderHeight=64,Inset=20,ActionSize=32,ActionGap=4;
 public static Grid Header(UIElement title,params Button[] actions){var grid=new Grid{Height=HeaderHeight,Margin=new Thickness(Inset,0,Inset,0)};grid.ColumnDefinitions.Add(new());if(title is FrameworkElement visual)visual.VerticalAlignment=VerticalAlignment.Center;grid.Children.Add(title);for(int i=0;i<actions.Length;i++){if(i>0)grid.ColumnDefinitions.Add(new(){Width=new GridLength(ActionGap)});grid.ColumnDefinitions.Add(new(){Width=new GridLength(ActionSize)});var button=actions[i];button.Margin=new Thickness(0);Grid.SetColumn(button,grid.ColumnDefinitions.Count-1);grid.Children.Add(button);string role=actions.Length==1?"CloseSettings":i==actions.Length-1?"Close":i==actions.Length-2?"Pin":i==actions.Length-3?"Settings":"Extra";System.Windows.Automation.AutomationProperties.SetAutomationId(button,"Suite."+role);}return grid;}
 static System.Collections.Generic.IEnumerable<Button> Buttons(DependencyObject root){if(root is Button button)yield return button;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Buttons(VisualTreeHelper.GetChild(root,i)))yield return child;}
 public static bool Aligned(Window root,bool settings=false,double headerHeight=HeaderHeight){root.UpdateLayout();string[] roles=settings?new[]{"CloseSettings"}:new[]{"Close","Pin","Settings"};for(int i=0;i<roles.Length;i++){Button? found=null;foreach(var candidate in Buttons(root))if(System.Windows.Automation.AutomationProperties.GetAutomationId(candidate)=="Suite."+roles[i]){found=candidate;break;}if(found==null)return false;var point=found.TranslatePoint(new Point(found.ActualWidth/2,found.ActualHeight/2),root);double edge=1+Inset+ActionSize/2+i*(ActionSize+ActionGap);double expected=root.FlowDirection==FlowDirection.RightToLeft?edge:root.ActualWidth-edge;if(Math.Abs(point.X-expected)>1||Math.Abs(point.Y-(1+headerHeight/2))>1||Math.Abs(found.ActualWidth-ActionSize)>1||Math.Abs(found.ActualHeight-ActionSize)>1)return false;}return true;}
}


